   [E("Completa: «(Había / Habían) tres gatos en el techo».", "Había", "Haber como existir va en singular."),
    E("En «Deja tu mochila ahí», ¿qué indica «ahí»: un lugar o una acción?", "Un lugar", "Señala dónde dejar la mochila."),
    E("Completa: «Vamos (a ver / haber) qué hay dentro de la caja».", "a ver", "Significa mirar o comprobar.")],
