L(OA22, 3,
  "Este cuaderno, lápiz y una hoja. Las oraciones vienen escritas.",
  "Aprenderé a usar la coma en frases explicativas. Sirve para agregar información sin que el mensaje principal se pierda.",
  ["Sé usar la coma en enumeraciones.", "Sé qué es una oración."],
  ["Una frase explicativa agrega información sobre alguien o algo y se puede quitar sin que la oración pierda su sentido principal. Se escribe entre comas. «Rapa Nui, isla del océano Pacífico, pertenece a Chile» se puede leer «Rapa Nui pertenece a Chile» sin problema. Esa información extra va entre dos comas.",
   "Hay dos tipos. La aposición es una palabra o grupo de palabras que explica a un sustantivo: «Pablo Neruda, poeta chileno, nació en Parral». La oración explicativa comienza con «que» y también se escribe entre comas: «Mi abuelo, que vive en Osorno, llega mañana». Si la frase está al final de la oración, lleva una sola coma: «Visitamos Valdivia, ciudad del sur de Chile».",
   "Si la información es necesaria para saber de quién se habla, no lleva comas: «Los niños que no hicieron la tarea deberán repetirla» se refiere solo a algunos niños. En cambio, «Los niños, que no hicieron la tarea, deberán repetirla» dice que todos no la hicieron. Las comas cambian el significado, así que se ponen con cuidado."],
  [("frase explicativa", "frase que agrega información y se escribe entre comas"), ("aposición", "palabra o grupo que explica a un sustantivo"), ("oración explicativa", "oración con «que» que agrega información"), ("sustantivo", "palabra que nombra personas, animales o cosas"), ("mensaje principal", "idea central de la oración"), ("necesaria", "que no se puede quitar sin cambiar el sentido")],
  [("Comas en una aposición", "Pon las comas: «El cóndor ave de gran tamaño vive en los Andes».", ["Busco la información extra: «ave de gran tamaño».", "Se puede quitar sin que cambie el mensaje.", "La encierro entre comas."], "«El cóndor, ave de gran tamaño, vive en los Andes»."),
   ("Sin comas porque es necesaria", "¿Lleva comas «que no hicieron la tarea» en «Los niños que no hicieron la tarea deberán repetirla»?", ["Si la quito, no sé de qué niños se habla.", "La información es necesaria.", "No lleva comas."], "No lleva comas.")],
  [("Poner una sola coma cuando la frase está en medio.", "Quedan dos ideas separadas mal.", "Abre y cierra la frase con dos comas."),
   ("Poner comas a una frase necesaria.", "Cambia el significado.", "Prueba quitarla: si hay que saber a quién se refiere, no lleva coma.")],
  ([E("En «Santiago, capital de Chile, tiene muchos parques», ¿cuál es la frase explicativa?", "capital de Chile", "Agrega información sobre Santiago y va entre comas."),
    E("En «Mi tía, que vive en Temuco, nos visitó», ¿qué parte se puede quitar sin perder el mensaje principal?", "que vive en Temuco", "Es información extra."),
    E("Cuando una frase explicativa va en medio de la oración, ¿cuántas comas lleva: una o dos?", "Dos", "Una abre y otra cierra la frase.")],
   [E("¿Cuál oración está bien escrita? A: «Rapa Nui, isla del océano Pacífico, pertenece a Chile». B: «Rapa Nui isla, del océano Pacífico pertenece a Chile».", "A", "Las comas encierran la frase explicativa."),
    E("¿Lleva comas «que no hicieron la tarea» en «Los estudiantes que no hicieron la tarea deberán repetirla»?", "No", "Identifica de qué estudiantes se habla."),
    E("En «Visitamos Valdivia, ciudad del sur de Chile», ¿cuántas comas lleva la frase explicativa final?", "Una", "Al final de la oración no se cierra con otra coma.")],
   [E("¿Cuál está bien escrita? A: «El volcán Osorno, que está en el sur de Chile, tiene nieve». B: «El volcán Osorno que está en el sur de Chile, tiene nieve».", "A", "La oración explicativa va entre dos comas."),
    E("¿Cuál está bien escrita? A: «Gabriela Mistral, poeta chilena, recibió el Premio Nobel de Literatura en 1945». B: «Gabriela Mistral poeta chilena recibió el Premio Nobel de Literatura en 1945».", "A", "La aposición «poeta chilena» va entre comas."),
    E("¿Cuál está bien escrita? A: «Mi perro, un cachorro de dos meses, duerme mucho». B: «Mi perro un cachorro, de dos meses duerme mucho».", "A", "La aposición se encierra entre dos comas.")],
   [E("«Los niños, que son estudiosos, aprobaron». ¿Aprobaron todos los niños o solo algunos?", "Todos", "Las comas indican que ser estudiosos es información extra sobre todos."),
    E("«Los niños que son estudiosos aprobaron». ¿Aprobaron todos los niños o solo los estudiosos?", "Solo los estudiosos", "Sin comas, la frase identifica a quiénes.")],
   [E("Pon las comas a «Mi hermana mayor que estudia en Concepción vendrá el viernes» pensando que tengo una sola hermana mayor. ¿Cuántas comas necesita?", "2", "La oración explicativa va entre dos comas."),
    E("¿Cuántas comas lleva «Pablo Neruda poeta chileno nació en Parral»?", "2", "La aposición va entre dos comas.")]),
  [E("Aviso del curso: «El profesor de música el señor Soto ensayará con el coro». ¿Cuántas comas necesita para encerrar la aposición «el señor Soto»?", "2", "Una abre y otra cierra la aposición.")],
  [E("¿Una frase explicativa en medio de la oración se escribe entre comas o entre guiones bajos?", "Entre comas", "Es la regla de puntuación."),
   E("¿Qué comienza una oración explicativa: «que» o «aunque»?", "«que»", "Es el nexo típico de la oración explicativa."),
   E("Si la información es necesaria para identificar de quién se habla, ¿lleva comas?", "No", "Sin ella, el mensaje cambia.")],
  ("Escribe cuatro oraciones sobre tu familia, tu barrio o un animal que conozcas. Cada una debe tener una frase explicativa entre comas. Por ejemplo: «Mi vecina, que tiene un gato negro, es muy amable».",
   "«Mi abuela, una gran cocinera, prepara pastel de choclo. Mi barrio, que está cerca del río, es tranquilo. Rayo, el perro de mi tío, ladra mucho. Mi escuela, fundada hace muchos años, tiene un patio grande».",
   ["cada oración tiene una frase explicativa", "usa dos comas cuando va en medio", "la información es extra"], ["cuatro oraciones"], ["poner una sola coma", "poner comas a una frase necesaria"],
   "Lee la oración sin la frase explicativa para comprobar que sigue completa."),
  "Busca una aposición en un libro y cópiala con sus comas.",
  "Escribe dos oraciones que cambien de sentido según lleven o no comas, como la de los niños estudiosos.")

